"""Inspected source register for M. Venkaiah Naidu. No network during rebuild."""
ASOF='2026-11-08'
sources=[]; retrievals=[]
def src(n,title,author,url,date,kind,locator,passage,note='',status='Passage inspected',origin=None):
    sid=f'S{n:03d}'; origin=origin or sid
    sources.append({'Source ID':sid,'Title':title,'Author / institution':author,'URL':url,'Publication date':date,'Access date':ASOF,'Source class':kind,'Primary / secondary':'Primary' if kind in ['Official record','Speech','Court order','Statute'] else 'Secondary','Access status':status,'Origin ID':origin,'Locator':locator,'Reliability / limitation':note or 'Supports the inspected passage only; distinguish recorded action from outcomes.','Language / geography':'English / India'})
    retrievals.append({'id':f'R{n:03d}','source_id':sid,'url_or_query':url,'access_date':ASOF,'route':'Canonical page or identified institutional mirror','access_status':status,'origin_id':origin,'locator':locator,'passage_paraphrase':passage,'method':'web.run passage inspection','result':status,'next_action':'Reuse inspected historical evidence; refresh only time-sensitive claims.'})
src(1,'Shri M. Venkaiah Naidu: former Vice-President profile','Vice President of India','https://vicepresidentofindia.nic.in/former-head/shri-m-venkaiah-naidu/',None,'Official record','Profile and Positions Held; lines 78–118','Born 1 July 1949, Chavatapalem, Nellore; B.A., B.L.; student union posts in 1971 and 1973–74; JP movement 1974; Janata youth leadership 1977–80; Assembly 1978–85; BJP state general secretary 1985–88, president 1988–93, national general secretary 1993–September 2000. Rural Development 30 September 2000–30 June 2002. BJP president July 2002–December 2003 and January–October 2004. Rajya Sabha elected 1998, 2004, 2010, 2016. Vice-President/Chairman 11 August 2017–10 August 2022.','Historical official biography; election month labels may refer to term starts. Its 2017 urban titles need reconciliation with ministry merger notification. UN Habitat title is imprecise: use Governing Council presidency only after separate check.',origin='VP-BIO')
src(2,'Rajya Sabha: biographical sketches of members','Rajya Sabha Secretariat','https://cms.rajyasabha.nic.in/UploadedFiles/ElectronicPublications/Member_Biographical_Book.pdf',None,'Official record','Indexed p.8, Naidu entry','Indexed member terms: 3 April 1998–2 April 2004; 1 July 2004–30 June 2010; 1 July 2010–23 June 2016; 5 July 2016–10 August 2017.','Web full-document retrieval timed out. Exact dates remain provisional until full text is inspected.',status='Search excerpt only',origin='RS-BIO')
src(3,'Welcome Mr. Chairman, Sir (Shri M. Venkaiah Naidu)','Rajya Sabha Secretariat','https://cms.rajyasabha.nic.in/UploadedFiles/ElectronicPublications/Welcome_Mr_%20Chairman_Sir_Shri_M_Venkaiah_Naidu.pdf','2017','Official record','Printed pp.i–iii; preface; 11 August 2017 felicitation speeches','Profile records MISA imprisonment during Emergency; BJP spokesman 1996–2000; senior vice-president April 2005–January 2006; Parliamentary Board/Central Election Committee January 2006–July 2017; Petitions Committee chair September 2006–September 2009; Home Affairs Committee chair August 2009–May 2014; Enemy Property subcommittee April–November 2011. Preface records cross-party welcomes, expectations of impartiality, and his call for constructive debate and cooperative federalism.','Felicitation speeches are ceremonial attributed assessments. Similar biography to S001 is not independent corroboration.',origin='VP-BIO')
src(4,'Vajpayee rewards Venkaiah on his 53rd birthday','Syed Amin Jafri / Rediff','https://www.rediff.com/news/2002/jul/01bjp3.htm','2002-07-02','Journalism','Career profile paragraphs, lines 58–104','Reports elevation to BJP presidency on 1 July 2002; Jai Andhra student activism, JP movement, Emergency imprisonment, Janata-to-BJP transition in 1980, role in 1984 NTR restoration campaign and ties with Chandrababu Naidu; characterises him as organisationally influential with limited home-state mass following.','Contains demonstrable errors: calls 1978 maiden election despite ECI 1977 Ongole result; places 1985 defeat in Udayagiri rather than Atmakur; alleges a 1991 loss not yet substantiated. These claims are excluded from accepted chronology.')
src(5,'Statistical Report: Andhra Pradesh Assembly election 1978','Election Commission of India / CEO Telangana archive','https://ceotelangana.nic.in/Archives/StasticalReports/StatRep_AP_1978.pdf','1978','Official record','Printed pp.139 and 329; PDF pp.141 and 331; constituency 124 Udayagiri','Muppavarapu Venkaiah Naidu, JNP: 33268; Janakiram Madala, INC(I): 23608; valid votes 69328; polled 70436; electors 103904; poll 25 February 1978.','Margin is 9660 by subtraction, not the erroneous 9960 found in some secondary tables.',origin='ECI-AP1978')
src(6,'Statistical Report: Andhra Pradesh Assembly election 1983','Election Commission of India / CEO Telangana archive','https://ceotelangana.nic.in/Archives/StasticalReports/StatRep_AP_1983.pdf','1983','Official record','Constituency 124 Udayagiri; indexed printed p.141','BJP Venkaiah Naidu Muppavarapu: 42694; INC Mekapati Rajamohan Reddy: 22194; valid votes 71715; polled 72790; electors 109166; margin 20500.','Web retrieval timed out twice; indexed date string 01-05-1983 must not be interpreted without inspecting original.',status='Search excerpt only',origin='ECI-AP1983')
src(7,'Statistical Report: Andhra Pradesh Assembly election 1985','Election Commission of India / CEO Telangana archive','https://ceotelangana.nic.in/Archives/StasticalReports/StatRep_AP_1985.pdf','1985','Official record','Printed p.333; PDF p.335; constituency 128 Atmakur','Sundara Ramireddy Bommireddy, INC: 46105; Muppavarapu Venkaiah Naidu, BJP: 45275; other candidates 1076 and 1049; valid 93505; polled 94680; electorate 132642. Naidu lost by 830.','Official result resolves Atmakur versus Udayagiri discrepancy; preserve undivided Andhra Pradesh geography.',origin='ECI-AP1985')
src(8,'General Elections 1977, Volume II','Election Commission of India','https://www.eci.gov.in/eci-backend/public/api/download?url=LMAhAK6sOPBp%2FNFF0iRfXbEB1EVSLT41NNLRjYNJJP1KivrUxbfqkDatmHy12e%2FzVx8fLfn2ReU7TfrqYobgIhgPqEQTyVU4arFX4liFqVq9M%2FhpEmpY6Ixg6YcsglGX509rV4dCDpdcKeQlrtlsTLSE2chQTOCwAEPcjz1eCk%2BZg1kgfO4p0vV0YQYWKtQq','1977','Official record','Constituency summary 18, Ongole; printed p.20','Puli Venkata Reddy INC 252206; Muppavarapu Venkaiah alias Venkaiah Naidu BLD 162881; valid 450638; polled 462001; electors 741462; poll 16 March 1977; margin 89325.','PDF metadata/title misleadingly mentions LS99; internal report identifies 1977. BLD is the recorded party label, not BJP.',origin='ECI-LS1977')
src(9,'General Elections 1989, Volume I','Election Commission of India','https://www.eci.gov.in/eci-backend/public/api/download?url=LMAhAK6sOPBp%2FNFF0iRfXbEB1EVSLT41NNLRjYNJJP1KivrUxbfqkDatmHy12e%2FzVx8fLfn2ReU7TfrqYobgInMRAMNg8PaP0CwQDgvm1TfOwdQ7ZrKZOu5S2TOM%2BKJg0H%2FFEltHcGuurSDHpdXYBA3aZmTyznbxm%2BIMcg53UkoRxiJFiG%2FG946CDJF6vuho','1989','Official record','Detailed result: constituency 16 Bapatla; web lines 22866–22899','Salagala Benjamin INC 364008; Muppavarapu Venkaiah Naidu BJP 320388; valid votes 697980; polled 724960; electorate 999676; turnout 72.52%.','Use valid votes for share and all polled votes for turnout; secondary sites sometimes confuse them.',origin='ECI-LS1989')
src(10,'General Elections 1996, Volume I','Election Commission of India','https://www.eci.gov.in/eci-backend/public/api/download?url=LMAhAK6sOPBp%2FNFF0iRfXbEB1EVSLT41NNLRjYNJJP1KivrUxbfqkDatmHy12e%2FzVx8fLfn2ReU7TfrqYobgIuTuCk2PkeBIxFg6I0eU5VPBleY%2F6DYULm%2FuXGBfnzIL0Ossb%2FOZWQZAC46suNmXLGuKAvNGAd8XYdXG8yyL7DmzUC9jIpIidmbrBMwxOPlx','1996','Official record','Printed pp.199–200; Hyderabad, constituency 30','Sultan Salahuddin Owaisi AIMIM 321045; M. Venkaiah Naidu BJP 247772; valid 928704; polled 949560; electors 1498515; turnout 63.37%.','Denominator appears after the full candidate list; preceding 726166 belongs to another constituency.',origin='ECI-LS1996')
src(11,'General Elections 1991, Volume I','Election Commission of India / ForumIAS mirror','https://forumias.sgp1.digitaloceanspaces.com/community/comments/1991-Vol-I4651634924352.pdf','1991','Official record','Printed p.131, Bapatla; text search VENKAIAH','Bapatla BJP candidate was Chandra Sekhara Rao Nasana (18222), not M. Venkaiah Naidu. Full-document web search for VENKAIAH returned no match.','A failed name search alone cannot prove no contest elsewhere. Source disputes Rediff’s asserted 1991 loss but requires broader candidate-list review; mirror shares ECI origin.',origin='ECI-LS1991')
src(12,'Women, Political Parties and Social Movements in South Asia','Amrita Basu / UNRISD','https://iknowpolitics.org/sites/default/files/political20parties20in20south20asia20_unrisd.pdf','2005-07','Academic','India section VI.A, printed pp.26–27','Basu challenges Naidu’s explanation that few women candidates were available, contrasting party nomination practices with women candidates’ electoral performance; acknowledges selection into winnable seats as an alternative explanation.','Historical party-level figures mostly precede his 2002 presidency. Do not attribute all earlier nomination decisions personally to him or turn selected-candidate success into causal proof.')

src(13,'Annual Report 2017–18','Ministry of Housing and Urban Affairs','https://www.mohua.gov.in/upload/uploadfiles/files/new_AR-2017-18%20%28Eng%29-Website.pdf','2018','Official record','Sections 2.01–2.02; 5.01–5.06','Urban Development and Housing/Urban Poverty Alleviation merged on 6 July 2017 under SO2163(E); Naidu served as first Housing and Urban Affairs minister until 17 July. AMRUT launched 25 June 2015, covering 500 cities with water and sewerage priorities and a five-year central allocation of Rs 50000 crore.','Report extends beyond his tenure; distinguish targets and subsequent outputs from his own delivery.')
src(14,'Rajya Sabha proceedings, 7 March 2001: rural roads','Rajya Sabha / Minister M. Venkaiah Naidu','https://cms.rajyasabha.nic.in/UploadedFiles/Debates/OfficialDebatesDatewise/Floor/192/F07.03.2001.pdf','2001-03-07','Official record','Printed p.23; PDF p.25','Naidu answers that PMGSY launched 25 December 2000, targeting connectivity to habitations above 1000 population by 2003 and above 500 by 2007, with state implementation under central guidelines.','Launch and targets, not verified completion of every road.')
src(15,'Consideration and passing of the Real Estate Bill','Lok Sabha / Indian Kanoon reproduction','https://indiankanoon.org/doc/138017247/','2016-03-15','Official record','Opening motion and Naidu reply','Naidu moves consideration of the Real Estate (Regulation and Development) Bill; acknowledges earlier bill and negotiations; Lok Sabha passes it.','Primary debate reproduced by legal database; distinguishes sponsorship from sole authorship.')
src(16,'Real Estate Act comes into force tomorrow','Press Information Bureau / HUPA','https://www.pib.gov.in/newsite/erelcontent.aspx?lang=2&reg=48&relid=161408','2017-04-30','Official record','Implementation requirements and legislative chronology','All 92 sections become effective 1 May 2017; registration, 70 percent separate project account and five-year defect responsibility. Bill introduced in 2013, passed Rajya Sabha 10 March and Lok Sabha 15 March 2016; assent 25 March 2016.','Government explanation of enacted safeguards; not independent assessment of compliance.')
src(17,'Letter to Uttar Pradesh Chief Minister on Smart Cities','M. Venkaiah Naidu / Uttar Pradesh local bodies archive','https://localbodies.up.nic.in/DLBGO/221%20%2007-04-2016.pdf','2016-03-02','Speech','Minister letter pp.1–3','Twenty cities selected from 97 proposals; letter describes fast-track and later rounds, asks for special-purpose vehicles before first central funding and stable three-year tenures for key municipal officers.','Direct evidence of ministerial implementation method.')
src(18,'Demystifying the Indian Smart City','Persis Taraporevala / Centre for Policy Research','https://www.cprindia.org/system/tdf/working_papers/SCM%20Working%20paper%2010th%20Aug.pdf',None,'Academic','Introduction and discussion of SPV/municipal relationships','Examines infrastructure finance, debt markets and continuity with earlier urban renewal; questions unclear division of power between special-purpose vehicles and elected municipal government.','Independent institutional critique; not a causal evaluation of Naidu personally.')
src(19,'Road connectivity and rural economic development: evidence from India’s rural roads','Adukia, Asher and Novosad / VoxDev','https://www.voxdev.org/topic/infrastructure/road-connectivity-and-rural-economic-development-evidence-indias-rural-roads',None,'Academic','Research findings; lines 48–80','Authors summarise threshold-based PMGSY research: roads encouraged movement out of agriculture and schooling; no substantial measured gains in consumption, income or assets over the studied horizon.','Findings concern studied villages and later road construction; no personal causal attribution to initial minister.')
src(20,'Rajya Sabha 2017–2022: An Overview','Rajya Sabha Secretariat','https://cms.rajyasabha.nic.in/UploadedFiles/ElectronicPublications/rs2017_2022anoverview.pdf','2022','Official record','Productivity; committee monitoring; multilingual proceedings; women presiding','For 13 full sessions 244–256 through April 2022 reports 68.35 percent productivity; first five 42.77 and next eight 82.34. Interpretation expanded to all 22 scheduled languages on 18 July 2018. Kahkashan Perween presided over Question Hour on 20 July 2018. Reports committee monitoring and longer average meetings.','Institutional retrospective favouring achievements; 13 sessions are not the full five-year tenure. Productivity is scheduled time used, not legislative quality.')
src(21,'Election to the Office of Vice-President: background material','Election Commission of India','https://www.eci.gov.in/eci-backend/public/api/download?url=LMAhAK6sOPBp%2FNFF0iRfXbEB1EVSLT41NNLRjYNJJP1KivrUxbfqkDatmHy12e%2FzcyjgeFPh4LtAbjL4Y7X74UyENgRpQmxwURrfVfd77AUd%2F7r1SMbL88JBiPylObr0gKdCmUSHqA1uyd%2BQgGswdQ%3D%3D','2022','Official record','Printed p.26; PDF p.29; 2017 election','5 August 2017 result: Naidu 516, opponent Gandhi 244; valid votes 760, polled 771, invalid 11, eligible 785; quota 381; tenure 11 August 2017–10 August 2022.','Votes are MP ballots, not a popular vote or presidential weighted-vote total.')
src(22,'Address to BJP National Council, 27 October 2004','L. K. Advani / BJP library','https://library.bjp.org/jspui/bitstream/123456789/247/1/Lal%20Krishna%20Advani.pdf','2004-10-27','Speech','Opening paragraphs on leadership succession','Advani states that Naidu asked to relinquish presidency on 18 October, citing personal and family reasons; praises his approximately 26 months of leadership following the 2004 national election defeat.','Party testimony establishes stated reason, not private motive or immunity from political pressure.')
src(23,'Venkaiah Naidu’s response on allegations has raised more questions: Congress','IANS / Business Standard','https://www.business-standard.com/article/news-ians/venkaiah-naidu-s-response-on-allegations-has-raised-more-questions-congress-117072600959_1.html','2017-07-26','Journalism','Congress allegations and Naidu responses','Congress questioned trust development-charge exemptions, police vehicle purchases involving his son’s dealership, earlier land matters and an alleged FCRA notice. Naidu denied wrongdoing and described the timing as politically motivated; said other trusts received exemptions and earlier land cases had been dismissed.','Reports allegations and responses, not proof of misconduct. Court dismissal claims are his account unless independently checked.',origin='IANS-20170726')
src(24,'Akhil Bhartiya Upbhokta Congress v State of Madhya Pradesh, Civil Appeal 2965/2011','Supreme Court of India / SpotLaw reproduction','https://spotlawapp.com/judgementText/pdf/910012011/9100120110406004.pdf','2011-04-06','Court order','Paragraph 3(v); concluding orders','Identifies Naidu as first president of the Kushabhau Thakre Memorial Trust. Finds non-transparent allotment of 20 acres unlawful, quashes allotment/notifications and directs repossession and refund.','Land-allotment judgment concerning public property; it does not establish a personal criminal conviction of Naidu.')
src(25,'Criticism of ban on NDTV India is politically inspired, ill-informed: Naidu','The Indian Express','https://indianexpress.com/article/india/india-news-india/criticism-of-ban-on-ndtv-india-is-politically-inspired-ill-informed-venkaiah-naidu-3739506/','2016-11','Journalism','Minister’s defence of broadcast order','Naidu defends a one-day NDTV India prohibition over Pathankot coverage as a security/programme-code measure, citing the June 2015 rule and earlier government advisories.','Attributed ministerial rationale; does not itself establish broadcast harm.')
src(26,'Ban on NDTV India put on hold as I&B Ministry reviews order','Scroll','https://amp.scroll.in/article/820968/ban-on-ndtv-india-put-on-hold-as-i-b-ministry-reviews-order','2016-11-07','Journalism','Order put on hold and broadcaster response','One-day ban was put on hold pending ministry review. NDTV disputed that its coverage differed from others and challenged the order in court.','Administrative hold, not a judicial merits judgment clearing or condemning the broadcast.')
src(27,'Order declining admission of motion for removal of Chief Justice Dipak Misra','M. Venkaiah Naidu, Chairman Rajya Sabha','https://judicialcompetitiontimes.in/CommonFilesFolder/JobsFolder/CJI-resolution-impeachment-rejected-2018.pdf?page=hsn','2018-04-23','Official record','Paragraphs 11 and 21–22','Chairman refused admission of the removal notice, reasoning that allegations were conjectural and did not disclose proved misbehaviour warranting admission.','Reproduced signed order; threshold/admissibility decision, not an inquiry committee finding or parliamentary trial.')
src(28,'CJI impeachment plea: petition dismissed as withdrawn','The Indian Express','https://indianexpress.com/article/india/cji-dipak-misra-impeachment-plea-live-updates-congress-kapil-sibal-supreme-court-bench-reactions-5167845/','2018-05-08','Journalism','Withdrawal before five-judge bench; lines 92–115','Congress MPs’ challenge to Naidu’s rejection ended as withdrawn after counsel Kapil Sibal sought details of bench constitution; court declined that request.','Withdrawal did not produce a merits endorsement of Naidu’s reasoning.')
src(29,'Eight Opposition MPs suspended from Rajya Sabha','Krishn Kaushik / The Indian Express','https://indianexpress.com/article/india/rajya-sabha-ruckus-opposition-mps-suspended-derek-o-brien-6604378/','2020-09-21','Journalism','Suspension motion and chairman’s ruling; lines 19–49','House adopted a minister’s motion suspending eight MPs for the remainder of the session after 20 September disorder. Naidu rejected notice against Deputy Chairman Harivansh citing the required notice period.','Harivansh chaired farm-bill passage; Naidu chaired the following day’s proceedings. House suspension must not be described as his unilateral act.')
src(30,'Deputy Chairman’s account of division requests challenged by Rajya Sabha TV footage','Manoj C. G. / The Indian Express','https://indianexpress.com/article/india/dy-chairman-said-opp-wasnt-in-seat-when-asking-for-division-rs-tv-shows-otherwise-6617404/','2020-09-27','Journalism','Video reconstruction of 20 September; lines 20–67','Reporter’s review of parliamentary footage finds Siva and Ragesh in their seats demanding divisions, challenging Harivansh’s explanation. Secretariat sources cited distraction and disorder.','Independent journalistic review of video; direct presiding responsibility belonged to Harivansh, not Naidu.')
src(31,'No remorse: Chairman rejects appeal on suspension of 12 MPs','NDTV','https://www.ndtv.com/india-news/parliament-winter-session-opposition-pushes-back-on-mps-suspension-meets-rajya-sabha-chairman-m-venkaiah-naidu-2630154','2021-11-30','Journalism','Suspension dispute and responses','Twelve MPs suspended in winter session for August-session conduct; opposition questioned retrospective procedure. Naidu refused the appeal for revocation, citing lack of remorse and the House’s action.','Records competing procedural positions; no judicial validation located in this run.')
src(32,'Vice President calls for political empowerment of women','Press Information Bureau','https://www.pib.gov.in/PressReleasePage.aspx?PRID=1647998','2020-08-23','Speech','Speech on women’s empowerment','Naidu advocates reservation in Parliament and state assemblies, property equality, girls’ education and action against son preference and dowry.','Advocacy and policy preferences, not proof he enacted reservation or changed outcomes.')
src(33,'Venkaiah Naidu on Viksit Bharat 2047','Aflaha Saleem K. P. / The Week','https://www.theweek.in/news/india/2026/10/31/venkaiah-naidu-viksit-bharat-2047.html','2026-10-31','Journalism','Former Vice-President’s Thursday address; lines 102–109','Reports former Vice-President speaking on 29 October 2026 on civic duties, skills, constructive debate and the Viksit Bharat 2047 aspiration.','Evidence of public activity shortly before research cutoff; not a comprehensive current appointments register.')
src(34,'Padma Vibhushan citation: Shri M. Venkaiah Naidu','Government of India / Padma Awards','https://www.padmaawards.gov.in/Document/pdf/CitationsForTickets/2024/20243.pdf','2024','Official record','Award heading and social-service description','Government awards Padma Vibhushan in 2024 and praises public affairs career and Swarna Bharat Trust’s women/youth training and social work.','Award citation contains chronology errors (1999 rural ministry and inflated MLA/RS duration); use award and attributed commendation only.')
src(35,'Report of the Committee of the Whole, UN-Habitat Governing Council 26th session','UN-Habitat','https://unhabitat.org/sites/default/files/2019/05/hspgc26cwl.1-english_0.pdf','2017-05','Official record','Paragraph 21, election of officers','Naidu elected President of the Governing Council at the 26th session on 8 May 2017.','Council presidency is distinct from being executive head of the UN-Habitat agency; personal end date not established.')
src(36,'Swachh Survekshan 2017 and citizen feedback tools launched','Press Information Bureau / Urban Development Ministry','https://www.pib.gov.in/newsite/PrintRelease.aspx?lang=2&reg=48&relid=148459','2016','Official record','Survey design and app/helpline launch','Naidu launches a survey of 500 cities for 2017, combining municipal submissions, citizen feedback and independent observation, alongside Swachhata app and helpline 1969.','Administrative instrument and announcement; not proof of sanitation coverage or independently verified cleanliness gains.')
src(37,'Udayagiri Assembly election results','Elections.in','https://www.elections.in/andhra-pradesh/assembly-constituencies/udayagiri.html',None,'Reference','1983 candidate table','1983: BJP Venkaiah Naidu Muppavarapu 42694; INC Mekapati Rajamohan Reddy 22194; Naidu elected.','Secondary full table inspected; official 1983 report remains an indexed lead. Denominator omitted pending official verification.',origin='ELECTIONS-IN-AP1983')
src(38,'BJP promises Seemandhra ten years of special status if elected','PTI / NDTV','https://www.ndtv.com/elections-news/bjp-promises-seemandhra-ten-years-of-special-status-if-elected-559441','2014-04-30','Journalism','Rayachoty campaign speech; lines 294–305','Naidu promises ten years of special status to residual Andhra Pradesh if BJP wins at Centre; promotes Modi and Chandrababu leadership.','Campaign promise, not enacted entitlement.',origin='PTI-20140430')
src(39,'Financial package will help Andhra more than special status: Naidu','PTI / Business Standard','https://www.business-standard.com/article/economy-policy/financial-package-will-help-andhra-more-than-special-status-venkaiah-naidu-116091100367_1.html','2016-09-11','Journalism','Minister’s defence of package; lines 89–112','Naidu defends assistance package instead of special category status, claims it will benefit AP more and cites Finance Commission arrangements; article notes Centre stopped short of special status.','Package value and claim of superiority are his assertions, not audited disbursements or established legal impossibility.',origin='PTI-20160911')
src(40,'TRS, BJP hit back at Jairam Ramesh over corruption allegations','Yunus Y. Lasania / Mint','https://www.livemint.com/Politics/ypEKyGfBrI7kIiUnkUMjRI/TRS-BJP-hit-back-at-Jairam-Ramesh-over-corruption-allegatio.html','2017-07-25','Journalism','Responses by K. T. Rama Rao and K. Laxman; lines 309–316','Rao says police vehicles were purchased at DGS&D rates and trust concessions also applied to other nonprofits. BJP’s Laxman denies Naidu’s involvement in son’s business and daughter’s trust.','Independent reporting of responses; purchase counts differ from subsequent Congress account, so do not harmonise them into a verified count.')

src(41,'Venkaiah Naidu: From RSS to BJP’s most recognised southern face','IANS / Business Standard','https://www.business-standard.com/article/news-ians/venkaiah-naidu-from-rss-to-bjp-s-most-recognized-southern-face-profile-117071701272_1.html','2017-07-17','Journalism','Profile; lines 85–124','Describes RSS background, Emergency activism and imprisonment, role in NTR restoration campaign, cross-party friendships and alliterative political communication. BJP organisation and national leadership enabled his rise despite weak party position in much of southern India.','Retrospective profile overstates continuous Rajya Sabha service and uses pre-merger ministry titles; do not use for exact office endpoints.',origin='IANS-PROFILE-2017')
src(42,'Secularism safe in India, it is in our DNA: Naidu','Express News Service / The Indian Express','https://indianexpress.com/article/cities/ahmedabad/secularism-safe-in-india-its-in-our-dna-venkaiah-naidu-5515473/','2018-12-30','Journalism','ABVP convention speech; lines 94–110','Naidu defends Indian secularism as culturally rooted, urges non-discrimination and national service, and asks for education reflecting Indian history and heritage. Recalls opposing automation as a student and now urges adaptation to technological change.','Speech report; claims about secularism’s security and national superiority are his positions, not independently established conditions.')
src(43,'Sever ties with NDA, CPM tells Naidu','Times News Network / Times of India','https://timesofindia.indiatimes.com/city/hyderabad/sever-ties-with-nda-cpm-tells-naidu/articleshow/32404955.cms','2002-12-26','Journalism','B. V. Raghavulu’s criticism; lines 149–158','CPM asked Chandrababu Naidu to reconsider NDA support after Venkaiah Naidu advocated replicating the Gujarat electoral experience; criticised fundamentalism and the tension with the common agenda.','Two different Naidus appear: headline addresses Chandrababu, while the BJP president’s statement is Venkaiah’s. Original presidential speech retrieval remains incomplete.')
src(44,'Naidu rejects Congress notice for motion to end MPs’ suspension','Express News Service / The Indian Express','https://indianexpress.com/article/india/naidu-rejects-congress-notice-to-end-mp-suspension-7675198/','2021-12-16','Journalism','Notice of 15 December and secretariat explanation; lines 100–107','Congress sought termination of 12 MPs’ suspension. Naidu rejected notice; secretariat sources said it lacked the proposed motion text. Report discusses chairman’s power to amend notices.','Adds later procedural episode to 30 November report; unnamed-source explanation is attributed, not an independently inspected ruling.')

